import {AccessSession,accessConfiguration} from './runtime/access/session.js';
import {requestJson,browserClock,browserTimers} from './runtime/http-transport.js';
/** Small page-owned access UI. Public config contains only the selected mode, never provider secrets. */
export async function createAccessPanel({runtime,taskPanel,collaborationPanel,clearSelection,fetchImpl=globalThis.fetch.bind(globalThis),origin=location.origin,host=document.querySelector('.top-actions')}){
 const button=document.createElement('button');button.id='access-toggle';button.type='button';button.setAttribute('aria-haspopup','dialog');button.setAttribute('aria-controls','access-dialog');button.textContent='Access';host.append(button);
 const dialog=document.createElement('dialog');dialog.className='agent-interaction-dialog';dialog.id='access-dialog';dialog.setAttribute('aria-labelledby','access-title');
 dialog.innerHTML='<form><div class="panel-heading"><h2 id="access-title">Elyqreth access</h2><button type="button" data-access-close aria-label="Close access">×</button></div><p data-access-status role="status" aria-live="polite">Resolving access configuration...</p><div data-local-fields><label>Username<input name="username" autocomplete="username" maxlength="64" required></label><label>Password<input name="password" type="password" autocomplete="current-password" maxlength="256" required></label></div><div data-oidc-fields hidden><p>Use an API access token issued for this installation. No issuer password, ID token, refresh token or provider key. Elyqreth does not start an issuer redirect flow.</p><label>API access token<input name="accessToken" type="password" autocomplete="off" spellcheck="false" maxlength="16384"></label></div><button type="submit" data-access-submit>Sign in</button><button type="button" data-access-recheck hidden>Recheck access</button><button type="button" data-access-logout hidden>Sign out</button><p>The city simulation is public. Protected Agent data requires verified access. Credentials remain in page memory until logout or reload.</p></form>';
 document.body.append(dialog);const q=s=>dialog.querySelector(s);let session=null,off=()=>{},active=false,signature='',disposed=false,channel=null;
 const clearFields=()=>{q('[name=password]').value='';q('[name=accessToken]').value='';};
 const clear=()=>{active=false;signature='';taskPanel.disconnect();collaborationPanel.disconnect();runtime.disconnect();clearSelection();clearFields();};
 button.onclick=()=>{dialog.showModal();(q('[data-local-fields]').hidden?q('[name=accessToken]'):q('[name=username]')).focus();};
 const close=()=>{clearFields();dialog.close();button.focus();};q('[data-access-close]').onclick=close;dialog.addEventListener('cancel',e=>{e.preventDefault();close();});dialog.addEventListener('close',clearFields);
 const online=()=>void session?.revalidate(),visible=()=>{if(!document.hidden)void session?.revalidate();},hide=()=>{session?.leavePage();clearFields();};
 try{
  const config=accessConfiguration(await requestJson(origin+'/access-config.json',{fetchImpl,timers:browserTimers,clock:browserClock,timeoutMs:5000,headers:{Accept:'application/json'},maxBytes:1024}),origin);
  if(config.mode==='disabled'){button.remove();dialog.remove();return {dispose(){disposed=true;button.remove();}};}
  taskPanel.setAccountMode();collaborationPanel.setAccountMode();clear();
  q('[data-local-fields]').hidden=config.mode!=='local';q('[data-oidc-fields]').hidden=config.mode!=='oidc';for(const field of q('[data-local-fields]').querySelectorAll('input'))field.required=config.mode==='local';q('[name=accessToken]').required=config.mode==='oidc';
  session=new AccessSession({origin,mode:config.mode,fetchImpl});
  const render=()=>{if(disposed)return;const state=session.getSnapshot(),next=state.principal?JSON.stringify(state.principal):'';
   if(state.phase!=='AUTHENTICATED'){if(active)clear();}else if(!active||next!==signature){clear();active=true;signature=next;session.connect((token,authorizedFetch)=>{runtime.connect({baseUrl:origin,pageOrigin:origin,access:'account',token,fetchImpl:authorizedFetch});taskPanel.connectAccount({token,fetchImpl:authorizedFetch});collaborationPanel.connectAccount({token,fetchImpl:authorizedFetch});});}
   q('[data-access-status]').textContent=state.message;q('[data-access-submit]').disabled=state.phase==='INITIALIZING';q('[data-access-submit]').hidden=state.phase==='AUTHENTICATED';q('[data-access-logout]').hidden=state.phase!=='AUTHENTICATED';q('[data-access-recheck]').hidden=state.phase!=='AUTHENTICATED';if(dialog.open&&state.phase==='AUTHENTICATED'&&document.activeElement?.closest('[data-local-fields],[data-oidc-fields]'))q('[data-access-logout]').focus();q('[data-local-fields]').hidden=config.mode!=='local'||state.phase==='AUTHENTICATED';q('[data-oidc-fields]').hidden=config.mode!=='oidc'||state.phase==='AUTHENTICATED';button.textContent=state.phase==='AUTHENTICATED'?`Access: ${state.principal.role}`:state.phase==='EXPIRED'?'Sign in again':'Sign in';
  };
  off=session.subscribe(render);session.bootstrap();render();
  q('form').onsubmit=async e=>{e.preventDefault();if(['INITIALIZING','AUTHENTICATED'].includes(session.getSnapshot().phase))return;const input={username:q('[name=username]').value,password:q('[name=password]').value,accessToken:q('[name=accessToken]').value};clearFields();await session.login(input);input.password='';input.accessToken='';};
  q('[data-access-recheck]').onclick=async()=>{clear();q('[data-access-recheck]').disabled=true;await session.revalidate();q('[data-access-recheck]').disabled=false;};
  q('[data-access-logout]').onclick=()=>{clearFields();void session.logout();channel?.postMessage({type:'logout'});};
  if(typeof BroadcastChannel==='function'){channel=new BroadcastChannel('elyqreth.access.logout.v1');channel.onmessage=e=>{if(e.data?.type==='logout')session.remoteLogout();};}
  globalThis.addEventListener('online',online);document.addEventListener('visibilitychange',visible);globalThis.addEventListener('pagehide',hide);
 }catch{taskPanel.setAccountMode();collaborationPanel.setAccountMode();clear();q('[data-access-status]').textContent='Access configuration unavailable or invalid. Protected access stays closed.';q('[data-access-submit]').disabled=true;q('[data-local-fields]').hidden=true;}
 return {dispose(){disposed=true;off();session?.dispose();clear();channel?.close();globalThis.removeEventListener('online',online);document.removeEventListener('visibilitychange',visible);globalThis.removeEventListener('pagehide',hide);dialog.remove();button.remove();}};
}
